@Component
public class SfTokenProvider {

    private final RestClient restClient;
    private final AssertionSigner signer;   // our class: signs with the key from Secret Manager
    private final SfProperties props;
    private CachedToken cached;

    // constructor omitted

    public synchronized String token() {
        Instant refreshAt = (cached == null)
            ? Instant.MIN
            : cached.expiresAt().minus(Duration.ofMinutes(5));
        if (Instant.now().[[1]](refreshAt)) {
            String assertion = signer.sign(props.apiUserId(), [[2]]);
            MultiValueMap<String, String> form = new LinkedMultiValueMap<>();
            form.add("client_id", props.apiKey());
            form.add("company_id", props.companyId());
            form.add("grant_type", "urn:ietf:params:oauth:grant-type:saml2-bearer");
            form.add("assertion", assertion);
            form.add("new_token", "true");
            TokenResponse response = restClient.post()
                .uri("[[3]]")
                .contentType(MediaType.APPLICATION_FORM_URLENCODED)
                .body(form)
                .retrieve()
                .body(TokenResponse.class);
            cached = CachedToken.from(response, Instant.now());
        }
        return cached.value();
    }

    public String authorizationHeader() {
        return "[[4]] " + token();
    }
}
